$:set -euo pipefail
python3 - <<'PY'
from pathlib import Path
p=Path("workspaces/extractor-srs-design/runtime/html-response-parser.js")
s=p.read_text()
old='''      } else if (raw.length === 2 && typeof raw[0] === "string" && raw[0] === "P") {
        fail("UNSUPPORTED_TAG", "unresolved Promise tag is unsupported by complete export");
'''
new='''      } else if (raw.length === 2 && typeof raw[0] === "string" && raw[0] === "P") {
        // Preserve React Router's unresolved Promise reference without evaluating it.
        // This is opaque serialization metadata, not a resolved conversation value.
        value = { "$serializedType":"Promise", "value":raw[1] };
'''
assert s.count(old)==1
s=s.replace(old,new)
p.write_text(s)
t=Path("workspaces/extractor-srs-design/tests/html-response-parser.test.js")
v=t.read_text()
assert 'opaque Promise tag' not in v
v += '''
test("opaque Promise tag is preserved without executing or dereferencing", () => {
  const decoded=decodeTable([{"_1":2},"deferred",["P",3],{"_1":-1}],{slots:300000,graphNodes:300000,depth:100});
  assert.equal(decoded.root.deferred.$serializedType,"Promise");
  assert.equal(decoded.root.deferred.value,3);
});
'''
t.write_text(v)
print("PATCHED Promise tag passthrough")
PY
node --check workspaces/extractor-srs-design/runtime/html-response-parser.js
node --test --test-concurrency=4 workspaces/extractor-srs-design/tests/*.test.js workspaces/extractor-srs-design/input-validator.test.js
for f in workspaces/extractor-srs-design/runtime/html-response-parser.js workspaces/extractor-srs-design/tests/html-response-parser.test.js; do
 SHA="$(gh api "repos/BestNameYet/Terminals/contents/$f" --jq .sha)"
 CONTENT="$(base64 -w0 "$f")"
 COMMIT="$(gh api -X PUT "repos/BestNameYet/Terminals/contents/$f" -f message="Preserve opaque React Router Promise tags in shared-conversation decoder" -f content="$CONTENT" -f sha="$SHA" --jq .commit.sha)"
 echo "PUBLISHED $f $COMMIT"
done
